    body = [
        f"### {title}",
        "",
        "## Report metadata",
        "",
        f"- **Report kind**: `{kind}`",
        f"- **Failure class**: `{_safe_class_value(read_kv(class_file, 'FAILURE_CLASS', 'unrecoverable'))}`",
